import ast,sys
for f in ['main.py','schema.py','HTTP3_Just_Send.py','modules/byte_program.py','modules/capture_audit.py','modules/clock.py','modules/events.py','modules/fuzz_adapter.py']:
    tree = ast.parse(open(f).read())
    imported=set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names: imported.add((a.asname or a.name).split('.')[0])
        elif isinstance(n, ast.ImportFrom):
            for a in n.names: imported.add(a.asname or a.name)
    used={n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    src=open(f).read()
    unused=[i for i in imported if src.count(i)<2 and i not in used]
    print(f, 'possibly unused:', sorted(unused))
" && cd /workspace && python3 check.py /workspace/project
